import React from "react";
import "../assets/style/ExpenseSection.css"; // Pour le style

const ExpenseSection = () => {
  // Données de test pour les dépenses
  const expenses = [
    { category: "Nourriture", amount: 200 },
    { category: "Transport", amount: 100 },
    { category: "Loisirs", amount: 50 },
    { category: "Services", amount: 20 },
    { category: "Autres", amount: 10 },
  ];

  return (
    <section className="expense-section">
      <h2>Mes Dépenses</h2>
      <div className="expense-content">
        <div className="expense-cards">
          {expenses.map((expense, index) => (
            <div key={index} className="expense-card">
              <h3>{expense.category}</h3>
              <p>{expense.amount} €</p>
            </div>
          ))}
        </div>
        <div className="expense-image">
          <img src="/images/receipt.png" alt="Receipt" />
        </div>
      </div>
    </section>
  );
};

export default ExpenseSection;
